css:
.row{display:flex; justify-content:center; gap:20px; margin-top:-24px}
.row>li{flex:0 0 30%; aspect-ratio:1; border-radius:50%; overflow:hidden}
section{overflow:hidden; background:#faf8f2}   /* 地色＝隙間の色になる */
/* 隙間を完全に殺す側 */
.strip{display:flex; gap:0}
.strip img{flex:1 1 0; min-width:0; object-fit:cover}
